import { useState, useEffect, useCallback, useRef } from "react";
import { ethers } from "ethers";
import DotVaultABI from "../abi/DotVault.json";

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

const CONTRACT_ADDRESS = "0x73EA57A7A46413E6E4943F8e839De2abAe21CdE1";
const CHAIN_ID = 420420421;                  // Polkadot Hub Westend
const CHAIN_ID_HEX = "0x" + CHAIN_ID.toString(16);
const AUTO_REFRESH_MS = 15_000;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const EMPTY_VAULT_DATA = {
  totalDeposited: "0",
  sharePrice: "0",
  estimatedAPY: "0",
  depositorCount: "0",
};

function parseError(err) {
  // Custom contract errors
  if (err?.message?.includes("ZeroAmount")) return "Amount must be greater than zero.";
  if (err?.message?.includes("InsufficientShares")) return "Insufficient shares to withdraw.";
  if (err?.message?.includes("NotOwner")) return "Only the vault owner can call this.";
  if (err?.message?.includes("StakingFailed")) return "Staking precompile call failed.";
  if (err?.message?.includes("XCMFailed")) return "XCM cross-chain transfer failed.";
  if (err?.code === 4001) return "Transaction rejected by user.";
  if (err?.code === -32002) return "MetaMask request already pending.";
  return err?.reason ?? err?.message ?? "An unknown error occurred.";
}

// ---------------------------------------------------------------------------
// useVault hook
// ---------------------------------------------------------------------------

export function useVault() {
  const [account, setAccount] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const [vaultData, setVaultData] = useState(EMPTY_VAULT_DATA);
  const [userBalance, setUserBalance] = useState("0"); // share balance
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const providerRef = useRef(null);
  const signerRef = useRef(null);
  const contractRef = useRef(null); // read-only (provider)
  const rwContractRef = useRef(null); // read-write (signer)
  const refreshTimerRef = useRef(null);

  // -------------------------------------------------------------------------
  // Internal: build contract instances
  // -------------------------------------------------------------------------

  const buildContracts = useCallback((providerOrSigner, signerInstance = null) => {
    const abi = DotVaultABI.abi ?? DotVaultABI;
    contractRef.current = new ethers.Contract(CONTRACT_ADDRESS, abi, providerOrSigner);
    rwContractRef.current = signerInstance
      ? new ethers.Contract(CONTRACT_ADDRESS, abi, signerInstance)
      : contractRef.current;
  }, []);

  // -------------------------------------------------------------------------
  // Internal: fetch vault-level read data
  // -------------------------------------------------------------------------

  const fetchVaultData = useCallback(async () => {
    if (!contractRef.current) return;
    try {
      const [totalDeposited, sharePrice, estimatedAPY, depositorCount] = await Promise.all([
        contractRef.current.totalDeposited(),
        contractRef.current.sharePrice(),
        contractRef.current.estimatedAPY(),
        contractRef.current.depositorCount(),
      ]);

      setVaultData({
        totalDeposited: ethers.formatEther(totalDeposited),
        sharePrice: ethers.formatEther(sharePrice),
        estimatedAPY: estimatedAPY.toString(),   // basis points
        depositorCount: depositorCount.toString(),
      });
    } catch (err) {
      console.warn("[useVault] fetchVaultData error:", err);
    }
  }, []);

  // -------------------------------------------------------------------------
  // Internal: fetch per-user share balance
  // -------------------------------------------------------------------------

  const fetchUserBalance = useCallback(async (addr) => {
    if (!contractRef.current || !addr) return;
    try {
      const shares = await contractRef.current.balanceOf(addr);
      setUserBalance(ethers.formatEther(shares));
    } catch (err) {
      console.warn("[useVault] fetchUserBalance error:", err);
    }
  }, []);

  // -------------------------------------------------------------------------
  // Internal: refresh all data
  // -------------------------------------------------------------------------

  const refreshData = useCallback(async (addr) => {
    await Promise.all([
      fetchVaultData(),
      fetchUserBalance(addr ?? account),
    ]);
  }, [fetchVaultData, fetchUserBalance, account]);

  // -------------------------------------------------------------------------
  // Auto-refresh every 15 seconds
  // -------------------------------------------------------------------------

  const startAutoRefresh = useCallback((addr) => {
    if (refreshTimerRef.current) clearInterval(refreshTimerRef.current);
    refreshTimerRef.current = setInterval(() => refreshData(addr), AUTO_REFRESH_MS);
  }, [refreshData]);

  const stopAutoRefresh = useCallback(() => {
    if (refreshTimerRef.current) {
      clearInterval(refreshTimerRef.current);
      refreshTimerRef.current = null;
    }
  }, []);

  // -------------------------------------------------------------------------
  // connect() — MetaMask via BrowserProvider
  // -------------------------------------------------------------------------

  const connect = useCallback(async () => {
    setError(null);
    if (!window.ethereum) {
      setError("MetaMask not found. Please install the MetaMask extension.");
      return;
    }

    try {
      setLoading(true);

      // Request accounts
      const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
      const addr = accounts[0];

      // Switch / add the Polkadot Hub Westend network if needed
      try {
        await window.ethereum.request({
          method: "wallet_switchEthereumChain",
          params: [{ chainId: CHAIN_ID_HEX }],
        });
      } catch (switchErr) {
        if (switchErr.code === 4902) {
          await window.ethereum.request({
            method: "wallet_addEthereumChain",
            params: [{
              chainId: CHAIN_ID_HEX,
              chainName: "Polkadot Asset Hub Westend",
              nativeCurrency: { name: "WND", symbol: "WND", decimals: 18 },
              rpcUrls: ["https://eth-rpc-testnet.polkadot.io/"],
              blockExplorerUrls: ["https://assethub-westend.subscan.io"],
            }],
          });
        } else {
          throw switchErr;
        }
      }

      const provider = new ethers.BrowserProvider(window.ethereum);
      const signer = await provider.getSigner(addr); // pass addr directly to skip ENS lookup

      // Guard: make sure contract address is a real address, not a placeholder
      if (!ethers.isAddress(CONTRACT_ADDRESS)) {
        throw new Error(
          `CONTRACT_ADDRESS is not set. Open useVault.js and replace "${CONTRACT_ADDRESS}" with your deployed contract address.`
        );
      }

      providerRef.current = provider;
      signerRef.current = signer;

      buildContracts(provider, signer);

      setAccount(addr);
      setIsConnected(true);

      await refreshData(addr);
      startAutoRefresh(addr);

    } catch (err) {
      setError(parseError(err));
    } finally {
      setLoading(false);
    }
  }, [buildContracts, refreshData, startAutoRefresh]);

  // -------------------------------------------------------------------------
  // deposit(amountInDOT) — payable
  // -------------------------------------------------------------------------

  const deposit = useCallback(async (amountInDOT) => {
    setError(null);
    if (!rwContractRef.current) { setError("Wallet not connected."); return; }

    try {
      setLoading(true);
      const value = ethers.parseEther(String(amountInDOT));
      const tx = await rwContractRef.current.deposit({ value });
      await tx.wait();
      await refreshData();
    } catch (err) {
      setError(parseError(err));
    } finally {
      setLoading(false);
    }
  }, [refreshData]);

  // -------------------------------------------------------------------------
  // withdraw(shares) — shares as a decimal string e.g. "5.0"
  // -------------------------------------------------------------------------

  const withdraw = useCallback(async (shares) => {
    setError(null);
    if (!rwContractRef.current) { setError("Wallet not connected."); return; }

    try {
      setLoading(true);
      const shareBN = ethers.parseEther(String(shares));
      const tx = await rwContractRef.current.withdraw(shareBN);
      await tx.wait();
      await refreshData();
    } catch (err) {
      setError(parseError(err));
    } finally {
      setLoading(false);
    }
  }, [refreshData]);

  // -------------------------------------------------------------------------
  // harvestYield() — owner only
  // -------------------------------------------------------------------------

  const harvestYield = useCallback(async () => {
    setError(null);
    if (!rwContractRef.current) { setError("Wallet not connected."); return; }

    try {
      setLoading(true);
      // paraId=1000 (Asset Hub), amount=1 (min guard), weight=1_000_000
      const tx = await rwContractRef.current.harvestYield(
        1000,
        ethers.parseEther("1"),
        1_000_000n
      );
      await tx.wait();
      await refreshData();
    } catch (err) {
      setError(parseError(err));
    } finally {
      setLoading(false);
    }
  }, [refreshData]);

  // -------------------------------------------------------------------------
  // bridgeYield(paraId, amount, weight) — owner only
  // -------------------------------------------------------------------------

  const bridgeYield = useCallback(async (paraId, amount, weight = 1_000_000n) => {
    setError(null);
    if (!rwContractRef.current) { setError("Wallet not connected."); return; }

    try {
      setLoading(true);
      const amountBN = ethers.parseEther(String(amount));
      const tx = await rwContractRef.current.bridgeYieldToParachain(
        paraId,
        account,
        amountBN,
      );
      await tx.wait();
      await refreshData();
    } catch (err) {
      setError(parseError(err));
    } finally {
      setLoading(false);
    }
  }, [account, refreshData]);

  // -------------------------------------------------------------------------
  // Handle MetaMask account / chain changes
  // -------------------------------------------------------------------------

  useEffect(() => {
    if (!window.ethereum) return;

    const onAccountsChanged = (accounts) => {
      if (accounts.length === 0) {
        setAccount(null);
        setIsConnected(false);
        stopAutoRefresh();
      } else {
        setAccount(accounts[0]);
        refreshData(accounts[0]);
      }
    };

    const onChainChanged = () => {
      // Reload to avoid stale provider state
      window.location.reload();
    };

    window.ethereum.on("accountsChanged", onAccountsChanged);
    window.ethereum.on("chainChanged", onChainChanged);

    return () => {
      window.ethereum.removeListener("accountsChanged", onAccountsChanged);
      window.ethereum.removeListener("chainChanged", onChainChanged);
      stopAutoRefresh();
    };
  }, [refreshData, stopAutoRefresh]);

  // -------------------------------------------------------------------------
  // Public API
  // -------------------------------------------------------------------------

  return {
    // State
    account,
    isConnected,
    vaultData,
    userBalance,
    loading,
    error,
    // Actions
    connect,
    deposit,
    withdraw,
    harvestYield,
    bridgeYield,
    // Manual refresh
    refreshData,
  };
}

export default useVault;