import { useState, useEffect, useRef } from "react";
import useVault from "./hooks/useVault";

const ERA_DATA = [
    { era: 1421, apy: 12.4 },
    { era: 1422, apy: 13.1 },
    { era: 1423, apy: 11.8 },
    { era: 1424, apy: 14.2 },
    { era: 1425, apy: 13.7 },
];

const PARACHAIN_BUTTONS = [
    { label: "AssetHub", paraId: 1000, color: "#FFDE00" },
    { label: "Acala", paraId: 2000, color: "#3B4CCA" },
    { label: "Moonbeam", paraId: 2004, color: "#CC0000" },
];

const QUICK_AMOUNTS = [10, 50, 100, 500];

const PKM = {
    red: "#CC0000",
    darkRed: "#960000",
    yellow: "#FFDE00",
    darkYellow: "#B8A000",
    blue: "#3B4CCA",
    white: "#FFFFFF",
    offWhite: "#F8F8F0",
    black: "#1A1A1A",
    gray: "#707070",
    lightGray: "#E8E8E8",
    screenBg: "#98D8A0",
    screenDark: "#1C3A20",
};

const S = {
    root: {
        minHeight: "100vh",
        background: "linear-gradient(160deg, #CC0000 0%, #960000 40%, #1A1A1A 100%)",
        fontFamily: "'Courier New', Courier, monospace",
        color: PKM.black,
        position: "relative",
        overflow: "hidden",
    },
    pokeballBg: {
        position: "fixed", top: -120, right: -120, zIndex: 0,
        width: 400, height: 400, borderRadius: "50%",
        border: "40px solid rgba(255,255,255,0.06)",
        pointerEvents: "none",
    },
    wrap: {
        position: "relative", zIndex: 1,
        maxWidth: 1200, margin: "0 auto",
        padding: "0 24px 60px",
    },
    header: {
        display: "flex", alignItems: "center", justifyContent: "space-between",
        padding: "20px 0",
        borderBottom: `3px solid ${PKM.yellow}`,
        marginBottom: 24,
    },
    logoWrap: { display: "flex", alignItems: "center", gap: 14 },
    pokeball: {
        width: 38, height: 38, borderRadius: "50%",
        background: `linear-gradient(180deg, ${PKM.red} 50%, ${PKM.white} 50%)`,
        border: `3px solid ${PKM.black}`,
        position: "relative", flexShrink: 0,
        boxShadow: "2px 2px 0 rgba(0,0,0,0.4)",
    },
    pokeballCenter: {
        position: "absolute", width: 10, height: 10, borderRadius: "50%",
        background: PKM.white, border: `3px solid ${PKM.black}`,
        top: "50%", left: "50%", transform: "translate(-50%,-50%)", zIndex: 2,
    },
    pokeballMid: {
        position: "absolute", width: "100%", height: 3,
        background: PKM.black, top: "50%", transform: "translateY(-50%)",
    },
    logo: {
        fontSize: 28, fontWeight: 900, letterSpacing: "0.15em", color: PKM.yellow,
        textShadow: `3px 3px 0 ${PKM.black}`,
    },
    logoSub: {
        fontSize: 10, color: PKM.white, letterSpacing: "0.2em",
        textTransform: "uppercase", marginTop: 2,
    },
    eraTag: {
        fontSize: 12, fontWeight: "bold", color: PKM.yellow,
        padding: "6px 14px", background: PKM.black,
        border: `2px solid ${PKM.yellow}`,
        boxShadow: "2px 2px 0 rgba(0,0,0,0.5)",
    },
    connectBtn: (connected) => ({
        padding: "10px 22px",
        background: connected ? PKM.blue : PKM.yellow,
        border: `3px solid ${PKM.black}`,
        color: connected ? PKM.white : PKM.black,
        fontFamily: "inherit", fontSize: 12, letterSpacing: "0.1em",
        fontWeight: 900, cursor: connected ? "default" : "pointer",
        boxShadow: connected ? "none" : `3px 3px 0 ${PKM.black}`,
        textTransform: "uppercase",
    }),
    statsRow: {
        display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12,
        marginBottom: 20,
    },
    statCard: {
        background: PKM.white, border: `3px solid ${PKM.black}`,
        padding: "16px 18px 14px", position: "relative", overflow: "hidden",
        boxShadow: `4px 4px 0 ${PKM.black}`,
    },
    statLabel: {
        fontSize: 9, color: PKM.gray, letterSpacing: "0.14em",
        textTransform: "uppercase", marginBottom: 8, fontWeight: "bold", marginTop: 6,
    },
    statValue: (accent) => ({
        fontSize: 26, color: accent, fontWeight: 900, lineHeight: 1,
    }),
    statUnit: { fontSize: 10, color: PKM.gray, marginLeft: 4, fontWeight: "bold" },
    statStripe: (accent) => ({
        position: "absolute", top: 0, left: 0, right: 0, height: 5, background: accent,
    }),
    tabNav: {
        display: "flex", gap: 0, marginBottom: 20,
        border: `3px solid ${PKM.black}`,
        boxShadow: `4px 4px 0 ${PKM.black}`,
        background: PKM.black, overflow: "hidden",
    },
    tabNavBtn: (active, last) => ({
        flex: 1, padding: "12px 8px", textAlign: "center",
        fontFamily: "inherit", fontSize: 11, letterSpacing: "0.1em",
        textTransform: "uppercase", fontWeight: 900,
        background: active ? PKM.yellow : PKM.black,
        border: "none",
        borderRight: last ? "none" : `1px solid #444`,
        color: active ? PKM.black : PKM.gray,
        cursor: "pointer",
    }),
    panel: {
        background: PKM.white, border: `3px solid ${PKM.black}`,
        boxShadow: `4px 4px 0 ${PKM.black}`, marginBottom: 16,
    },
    panelHead: (color) => ({
        padding: "10px 16px", background: color || PKM.red,
        borderBottom: `3px solid ${PKM.black}`,
        fontSize: 11, color: PKM.white, letterSpacing: "0.14em",
        textTransform: "uppercase", display: "flex", alignItems: "center", gap: 8,
        fontWeight: 900,
    }),
    panelBody: { padding: "18px" },
    chartWrap: { display: "flex", alignItems: "flex-end", gap: 8, height: 80, padding: "0 4px" },
    bar: (pct, active) => ({
        flex: 1,
        background: active
            ? `linear-gradient(180deg, ${PKM.yellow} 0%, ${PKM.darkYellow} 100%)`
            : PKM.lightGray,
        height: `${pct}%`, transition: "height 0.4s ease", position: "relative",
        border: `2px solid ${active ? PKM.black : "#CCCCCC"}`,
    }),
    barLabel: {
        position: "absolute", bottom: -18, left: "50%", transform: "translateX(-50%)",
        fontSize: 8, color: PKM.gray, whiteSpace: "nowrap", fontWeight: "bold",
    },
    posRow: { display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 16 },
    posCard: {
        background: PKM.screenBg, padding: "12px 14px",
        border: `2px solid ${PKM.black}`, boxShadow: `2px 2px 0 ${PKM.black}`,
    },
    posLabel: {
        fontSize: 9, color: PKM.screenDark, letterSpacing: "0.12em",
        textTransform: "uppercase", marginBottom: 6, fontWeight: "bold",
    },
    posValue: { fontSize: 18, color: PKM.screenDark, fontWeight: 900 },
    xcmLabel: {
        fontSize: 10, color: PKM.gray, letterSpacing: "0.1em",
        textTransform: "uppercase", marginBottom: 8, fontWeight: "bold",
    },
    paraRow: { display: "flex", gap: 8, marginBottom: 12 },
    paraBtn: (color, active) => ({
        flex: 1, padding: "8px 0",
        background: active ? color : PKM.white,
        border: `2px solid ${active ? PKM.black : "#CCCCCC"}`,
        color: active ? PKM.white : PKM.gray,
        fontFamily: "inherit", fontSize: 10, letterSpacing: "0.1em",
        cursor: "pointer", fontWeight: 900, textTransform: "uppercase",
        boxShadow: active ? `2px 2px 0 ${PKM.black}` : "none",
    }),
    xcmInput: {
        width: "100%", boxSizing: "border-box",
        background: PKM.offWhite, border: `2px solid ${PKM.black}`,
        color: PKM.black, fontFamily: "inherit", fontSize: 14, fontWeight: "bold",
        padding: "10px 14px", marginBottom: 10, outline: "none",
    },
    xcmBtn: {
        width: "100%", padding: "11px 0",
        background: PKM.blue, border: `3px solid ${PKM.black}`,
        color: PKM.white, fontFamily: "inherit", fontSize: 11,
        letterSpacing: "0.12em", cursor: "pointer", fontWeight: 900,
        boxShadow: `3px 3px 0 ${PKM.black}`, textTransform: "uppercase",
    },
    tabRow: { display: "flex", borderBottom: `3px solid ${PKM.black}` },
    tab: (active) => ({
        flex: 1, padding: "13px 0", textAlign: "center",
        fontFamily: "inherit", fontSize: 11, letterSpacing: "0.12em",
        textTransform: "uppercase", fontWeight: 900,
        background: active ? PKM.red : PKM.white,
        border: "none", color: active ? PKM.white : PKM.gray,
        cursor: "pointer",
    }),
    quickRow: { display: "flex", gap: 8, margin: "12px 0 10px" },
    quickBtn: (active) => ({
        flex: 1, padding: "8px 0",
        background: active ? PKM.yellow : PKM.offWhite,
        border: `2px solid ${active ? PKM.black : "#CCCCCC"}`,
        color: active ? PKM.black : PKM.gray,
        fontFamily: "inherit", fontSize: 11, fontWeight: 900,
        cursor: "pointer", boxShadow: active ? `2px 2px 0 ${PKM.black}` : "none",
    }),
    input: {
        width: "100%", boxSizing: "border-box",
        background: PKM.offWhite, border: `3px solid ${PKM.black}`,
        color: PKM.black, fontFamily: "inherit", fontSize: 24, fontWeight: 900,
        padding: "12px 14px", marginBottom: 8, outline: "none",
    },
    previewBox: {
        background: PKM.offWhite, padding: "9px 14px", marginBottom: 6,
        fontSize: 11, color: PKM.gray, border: `2px solid ${PKM.lightGray}`,
        display: "flex", justifyContent: "space-between",
    },
    previewVal: { color: PKM.black, fontWeight: 900 },
    submitBtn: (loading) => ({
        width: "100%", padding: "14px 0", marginTop: 10,
        background: loading ? PKM.lightGray : PKM.red,
        border: `3px solid ${PKM.black}`,
        color: loading ? PKM.gray : PKM.white,
        fontFamily: "inherit", fontSize: 13, letterSpacing: "0.14em",
        cursor: loading ? "not-allowed" : "pointer",
        fontWeight: 900, textTransform: "uppercase",
        boxShadow: loading ? "none" : `4px 4px 0 ${PKM.black}`,
        display: "flex", alignItems: "center", justifyContent: "center", gap: 10,
    }),
    spinner: {
        width: 14, height: 14,
        border: "3px solid rgba(255,255,255,0.3)",
        borderTop: `3px solid ${PKM.white}`,
        borderRadius: "50%", animation: "spin 0.7s linear infinite",
    },
    toast: (visible) => ({
        position: "fixed", bottom: 28, right: 28, zIndex: 100,
        background: PKM.yellow, border: `3px solid ${PKM.black}`,
        padding: "14px 20px", fontSize: 12, color: PKM.black, maxWidth: 320,
        fontWeight: 900, boxShadow: `4px 4px 0 ${PKM.black}`,
        transform: visible ? "translateY(0)" : "translateY(20px)",
        opacity: visible ? 1 : 0, transition: "all 0.3s ease",
        pointerEvents: visible ? "auto" : "none",
    }),
    toastDot: {
        display: "inline-block", width: 8, height: 8, borderRadius: "50%",
        background: PKM.red, border: `2px solid ${PKM.black}`, marginRight: 8,
    },
};

// ── Sub-components ──────────────────────────────────────────────────────────

function PokeballIcon() {
    return (
        <div style={S.pokeball}>
            <div style={S.pokeballMid} />
            <div style={S.pokeballCenter} />
        </div>
    );
}

function StatCard({ label, value, unit, accent = PKM.red }) {
    return (
        <div style={S.statCard}>
            <div style={S.statStripe(accent)} />
            <div style={S.statLabel}>{label}</div>
            <div>
                <span style={S.statValue(accent)}>{value}</span>
                {unit && <span style={S.statUnit}>{unit}</span>}
            </div>
        </div>
    );
}

function APYChart({ eraData, liveAPY }) {
    const maxAPY = Math.max(...eraData.map(d => d.apy), parseFloat(liveAPY) || 0);
    return (
        <div>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 10 }}>
                <span style={S.xcmLabel}>APY / ERA (last 5)</span>
                <span style={{ fontSize: 12, color: PKM.red, fontWeight: 900 }}>
                    ⚡ Live: {liveAPY ? `${(parseInt(liveAPY) / 100).toFixed(2)}%` : "—"}
                </span>
            </div>
            <div style={S.chartWrap}>
                {eraData.map((d, i) => (
                    <div key={d.era} style={{
                        flex: 1, display: "flex", flexDirection: "column",
                        alignItems: "stretch", position: "relative", paddingBottom: 22,
                    }}>
                        <div style={S.bar((d.apy / maxAPY) * 100, i === eraData.length - 1)}>
                            <span style={{ ...S.barLabel, color: i === eraData.length - 1 ? PKM.red : PKM.gray }}>
                                {d.era}
                            </span>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

// ── MAIN APP ───────────────────────────────────────────────────────────────

export default function App() {
    const {
        account, isConnected, vaultData, userBalance,
        loading, error, connect, deposit, withdraw, harvestYield, bridgeYield,
    } = useVault();

    const [mainTab, setMainTab] = useState("vault");
    const [tab, setTab] = useState("deposit");
    const [amount, setAmount] = useState("");
    const [quickAmt, setQuickAmt] = useState(null);
    const [selectedPara, setSelectedPara] = useState(PARACHAIN_BUTTONS[0]);
    const [xcmAmount, setXcmAmount] = useState("");
    const [toast, setToast] = useState({ visible: false, msg: "" });
    const toastTimer = useRef(null);

    const showToast = (msg) => {
        if (toastTimer.current) clearTimeout(toastTimer.current);
        setToast({ visible: true, msg });
        toastTimer.current = setTimeout(() => setToast({ visible: false, msg: "" }), 4000);
    };

    useEffect(() => { if (error) showToast(`⚠ ${error}`); }, [error]);

    const numAmount = parseFloat(amount) || 0;
    const sharePriceNum = parseFloat(vaultData.sharePrice) || 1;
    const previewShares = tab === "deposit"
        ? (sharePriceNum > 0 ? (numAmount / sharePriceNum).toFixed(4) : "—")
        : (numAmount * sharePriceNum).toFixed(4);

    const handleQuick = (val) => { setQuickAmt(val); setAmount(String(val)); };

    const handleSubmit = async () => {
        if (!amount || numAmount <= 0) return;
        if (tab === "deposit") {
            await deposit(amount);
            showToast(`✓ Deposited ${amount} DOT!`);
        } else {
            await withdraw(amount);
            showToast(`✓ Withdrew ${amount} shares`);
        }
        setAmount(""); setQuickAmt(null);
    };

    const handleBridge = async () => {
        if (!xcmAmount || parseFloat(xcmAmount) <= 0) return;
        await bridgeYield(selectedPara.paraId, xcmAmount);
        showToast(`✓ Bridged to ${selectedPara.label}!`);
        setXcmAmount("");
    };

    const shortAddr = account
        ? `0x${account.slice(2, 6).toUpperCase()}...${account.slice(-4).toUpperCase()}`
        : null;
    const currentEra = ERA_DATA[ERA_DATA.length - 1].era + 1;

    const TABS = [
        { id: "vault", label: "🏦 Vault" },
        { id: "stats", label: "📊 Stats" },
        { id: "bridge", label: "🌉 XCM" },
        { id: "info", label: "ℹ️ Info" },
    ];

    return (
        <div style={S.root}>
            <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        * { box-sizing: border-box; }
        input:focus { border-color: #FFDE00 !important; outline: none; }
        button:active { transform: translate(2px,2px); box-shadow: none !important; }
        body { margin: 0; }
      `}</style>

            <div style={S.pokeballBg} />

            <div style={S.wrap}>

                {/* HEADER */}
                <header style={S.header}>
                    <div style={S.logoWrap}>
                        <PokeballIcon />
                        <div>
                            <div style={S.logo}>DOTVAULT</div>
                            <div style={S.logoSub}>Polkadot Yield · Track 2</div>
                        </div>
                    </div>
                    <div style={S.eraTag}>ERA #{currentEra}</div>
                    <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                        {isConnected && shortAddr && (
                            <span style={{
                                fontSize: 11, color: PKM.yellow, fontWeight: "bold",
                                background: "rgba(0,0,0,0.3)", padding: "4px 10px",
                                border: `1px solid ${PKM.yellow}`,
                            }}>
                                {shortAddr}
                            </span>
                        )}
                        <button style={S.connectBtn(isConnected)} onClick={connect} disabled={isConnected}>
                            {isConnected ? "● CONNECTED" : "CONNECT WALLET"}
                        </button>
                    </div>
                </header>

                {/* STATS ROW */}
                <div style={S.statsRow}>
                    <StatCard label="Total Deposited"
                        value={parseFloat(vaultData.totalDeposited).toFixed(2)} unit="DOT" accent={PKM.red} />
                    <StatCard label="Estimated APY"
                        value={vaultData.estimatedAPY
                            ? `${(parseInt(vaultData.estimatedAPY) / 100).toFixed(2)}` : "0.00"}
                        unit="%" accent={PKM.blue} />
                    <StatCard label="Share Price"
                        value={parseFloat(vaultData.sharePrice).toFixed(4)} unit="DOT" accent={PKM.black} />
                    <StatCard label="Depositors"
                        value={vaultData.depositorCount} accent={PKM.darkRed} />
                </div>

                {/* TAB NAVIGATION */}
                <div style={S.tabNav}>
                    {TABS.map((t, i) => (
                        <button
                            key={t.id}
                            style={S.tabNavBtn(mainTab === t.id, i === TABS.length - 1)}
                            onClick={() => setMainTab(t.id)}
                        >
                            {t.label}
                        </button>
                    ))}
                </div>

                {/* VAULT TAB */}
                {mainTab === "vault" && (
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
                        <div>
                            <div style={S.panel}>
                                <div style={S.panelHead(PKM.blue)}>🎮 Your Position</div>
                                <div style={S.panelBody}>
                                    {!isConnected ? (
                                        <div style={{ textAlign: "center", padding: "20px 0", color: PKM.gray, fontSize: 13, fontWeight: "bold" }}>
                                            ⚡ Connect wallet to see your stats
                                        </div>
                                    ) : (
                                        <div style={S.posRow}>
                                            {[
                                                { label: "Balance", value: `${parseFloat(userBalance).toFixed(4)} DOT` },
                                                { label: "Yield Earned", value: `${((parseFloat(userBalance) * (parseFloat(vaultData.sharePrice) - 1))).toFixed(4)}` },
                                                { label: "Shares", value: parseFloat(userBalance).toFixed(2) },
                                            ].map(item => (
                                                <div key={item.label} style={S.posCard}>
                                                    <div style={S.posLabel}>{item.label}</div>
                                                    <div style={S.posValue}>{item.value}</div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div style={{ ...S.panel, background: PKM.yellow }}>
                                <div style={S.panelHead(PKM.black)}>🏆 Track 2 Coverage</div>
                                <div style={{ padding: "14px 18px" }}>
                                    {[
                                        "✅  Polkadot Native Assets (DOT)",
                                        "✅  Staking Precompile 0x800",
                                        "✅  XCM Precompile 0x804",
                                        "✅  NativeAssets Precompile 0x806",
                                        "✅  Cross-chain XCM Bridge",
                                    ].map(item => (
                                        <div key={item} style={{ fontSize: 12, color: PKM.black, fontWeight: "bold", marginBottom: 6 }}>
                                            {item}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <div style={S.panel}>
                            <div style={S.tabRow}>
                                <button style={S.tab(tab === "deposit")} onClick={() => setTab("deposit")}>⬇ Deposit</button>
                                <button style={S.tab(tab === "withdraw")} onClick={() => setTab("withdraw")}>⬆ Withdraw</button>
                            </div>
                            <div style={{ padding: "22px 22px 26px" }}>
                                <div style={{ fontSize: 10, color: PKM.gray, letterSpacing: "0.12em", textTransform: "uppercase", marginBottom: 8, fontWeight: "bold" }}>
                                    {tab === "deposit" ? "Amount (DOT)" : "Shares to redeem"}
                                </div>
                                <input style={S.input} type="number" min="0" placeholder="0.00"
                                    value={amount} onChange={e => { setAmount(e.target.value); setQuickAmt(null); }} />
                                <div style={S.quickRow}>
                                    {QUICK_AMOUNTS.map(q => (
                                        <button key={q} style={S.quickBtn(quickAmt === q)} onClick={() => handleQuick(q)}>{q}</button>
                                    ))}
                                </div>
                                <div style={S.previewBox}>
                                    <span>{tab === "deposit" ? "Shares to receive" : "DOT to receive"}</span>
                                    <span style={S.previewVal}>{numAmount > 0 ? previewShares : "—"}</span>
                                </div>
                                <div style={S.previewBox}>
                                    <span>Share Price</span>
                                    <span style={S.previewVal}>{parseFloat(vaultData.sharePrice).toFixed(6)} DOT</span>
                                </div>
                                {tab === "withdraw" && (
                                    <div style={{ background: "#FFF8E1", border: `2px solid ${PKM.yellow}`, padding: "10px 14px", marginBottom: 8, fontSize: 11, color: "#7A5800", fontWeight: "bold" }}>
                                        ⚠ 28-day unbonding period applies
                                    </div>
                                )}
                                <button style={S.submitBtn(loading)} onClick={handleSubmit} disabled={!isConnected || loading || !amount}>
                                    {loading && <span style={S.spinner} />}
                                    {loading ? "CONFIRMING..." : tab === "deposit"
                                        ? `⬇ DEPOSIT ${amount || "0"} DOT`
                                        : `⬆ WITHDRAW ${amount || "0"} SHARES`}
                                </button>
                                {!isConnected && (
                                    <p style={{ textAlign: "center", fontSize: 11, color: PKM.gray, marginTop: 14, fontWeight: "bold" }}>
                                        Connect your wallet to interact
                                    </p>
                                )}
                            </div>
                        </div>
                    </div>
                )}

                {/* STATS TAB */}
                {mainTab === "stats" && (
                    <div style={S.panel}>
                        <div style={S.panelHead(PKM.blue)}>📊 APY History</div>
                        <div style={{ padding: "24px 24px 32px" }}>
                            <APYChart eraData={ERA_DATA} liveAPY={vaultData.estimatedAPY} />
                        </div>
                    </div>
                )}

                {/* XCM BRIDGE TAB */}
                {mainTab === "bridge" && (
                    <div style={S.panel}>
                        <div style={S.panelHead(PKM.blue)}>🌉 XCM Cross-Chain Bridge</div>
                        <div style={S.panelBody}>
                            <div style={{ fontSize: 13, color: PKM.gray, marginBottom: 16, fontWeight: "bold" }}>
                                Send vault yield cross-chain to any parachain via native XCM precompile (0x804).
                            </div>
                            <div style={S.xcmLabel}>Select Destination Parachain</div>
                            <div style={S.paraRow}>
                                {PARACHAIN_BUTTONS.map(p => (
                                    <button key={p.paraId} style={S.paraBtn(p.color, selectedPara.paraId === p.paraId)} onClick={() => setSelectedPara(p)}>
                                        {p.label}
                                        <div style={{ fontSize: 9, marginTop: 2, opacity: 0.8 }}>Para #{p.paraId}</div>
                                    </button>
                                ))}
                            </div>
                            <div style={S.xcmLabel}>Amount in DOT</div>
                            <input style={S.xcmInput} type="number" min="0"
                                placeholder={`Amount → ${selectedPara.label}`}
                                value={xcmAmount} onChange={e => setXcmAmount(e.target.value)} />
                            <button style={S.xcmBtn} onClick={handleBridge} disabled={!isConnected || loading}>
                                🌉 BRIDGE TO {selectedPara.label.toUpperCase()} →
                            </button>
                        </div>
                    </div>
                )}

                {/* INFO TAB */}
                {mainTab === "info" && (
                    <div style={S.panel}>
                        <div style={S.panelHead(PKM.black)}>ℹ️ Vault Info</div>
                        <div style={S.panelBody}>
                            {[
                                ["Network", "Polkadot Asset Hub"],
                                ["Chain ID", "420420420"],
                                ["Strategy", "NPoS Staking"],
                                ["Staking", "Precompile 0x0000...0800"],
                                ["XCM", "Precompile 0x0000...0804"],
                                ["NativeAssets", "Precompile 0x0000...0806"],
                                ["XCM Version", "V3"],
                                ["Unbonding", "~28 days"],
                                ["Est. APY", "~14.2%"],
                            ].map(([k, v], i) => (
                                <div key={k} style={{
                                    display: "flex", justifyContent: "space-between",
                                    padding: "10px 0",
                                    borderBottom: i < 8 ? `1px solid ${PKM.lightGray}` : "none",
                                    fontSize: 13,
                                }}>
                                    <span style={{ color: PKM.gray, fontWeight: "bold" }}>{k}</span>
                                    <span style={{ color: PKM.black, fontWeight: 900 }}>{v}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

            </div>

            {/* TOAST */}
            <div style={S.toast(toast.visible)}>
                <span style={S.toastDot} />
                {toast.msg}
            </div>
        </div>
    );
}
